import{_ as r,l as i,o as t,c as l,v as a,p as n,x as s,d as h,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"互连拓扑：mesh / torus / fat-tree","description":"","frontmatter":{"title":"互连拓扑：mesh / torus / fat-tree","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/interconnect-topologies.md","filePath":"cs/interconnect-topologies.md","lastUpdated":1789023840000}'),m={name:"cs/interconnect-topologies.md"};function p(E,e,u,_,f,B){const o=i("Mermaid");return t(),l("div",null,[e[1]||(e[1]=a('<h1 id="互连拓扑-mesh-torus-fat-tree" tabindex="-1">互连拓扑：mesh / torus / fat-tree <a class="header-anchor" href="#互连拓扑-mesh-torus-fat-tree" aria-label="Permalink to &quot;互连拓扑：mesh / torus / fat-tree&quot;">​</a></h1><div class="epigraph"><p>网格好铺硅、直径随边长涨；环面把边接回去减直径；胖树把拥塞赶到可加宽的上层，代价是层次与线长。</p><footer>—— 据 Dally and Towles；Leiserson, Fat-Trees, IEEE TC 1985 整理</footer></div><p><a href="/cs/noc-topology">上一课</a> 有了路由器，没说连成什么图。拓扑决定直径、对分带宽、以及目录 home 的最坏跳数。本课不重讲 flit。缺口是 <strong>mesh、torus、fat-tree 的几何与它们适合片上还是机柜。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 个 tile：全连接不可能。二维 mesh：每个内部节点 4 邻居，布线规则，直径 \\(O(\\sqrt{n})\\)，边角节点对分带宽窄。缺口不是再加虚通道定义，而是<strong>选图：延迟敏感的一致性要小直径，带宽敏感的 DMA 要对分带宽。</strong></p><p><span class="marginnote">Torus：mesh 的边绕回，直径减半，绕回线更长。Fat-tree：叶子是计算节点，向上链路加宽，Leiserson 用来逼近无阻塞。片上多用 mesh，机柜/超算多用 fat-tree 或类似。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>比较：度（路由器端口数）、直径、对分、是否规则布线。片上 mesh 与 tile 物理布局同构，几乎零交叉。Fat-tree 需要长线到根，片上难，片间交换机合适。多级交叉开关是胖树近亲。</p>',8)),(t(),n(c,null,{default:s(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20MESH%5B%222D%20mesh%22%5D%20--%3E%20D1%5B%22%E7%9B%B4%E5%BE%84%20O%20%E6%A0%B9%E5%8F%B7%20n%22%5D%0A%20%20TOR%5B%22torus%22%5D%20--%3E%20D2%5B%22%E6%9B%B4%E5%B0%8F%E7%9B%B4%E5%BE%84%EF%BC%8C%E7%BB%95%E5%9B%9E%E7%BA%BF%22%5D%0A%20%20FAT%5B%22fat-tree%22%5D%20--%3E%20BW%5B%22%E5%AF%B9%E5%88%86%E5%B8%A6%E5%AE%BD%E5%8F%AF%E5%A0%86%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>目录协议的延迟 ∝ 跳数 × 每跳（争用）。热点 home 在 mesh 中心还是角落，体验不同，所以地址哈希要均匀。GPU 的片上交叉或 mesh 服务 SM 到 L2；CPU 服务器 mesh 服务 LLC slice。多 socket 下一课之后才出芯片。</p><p>对分带宽决定「一半 tile 同时与另一半通信」时的上限，全 reduce、全交换一类集体操作吃这个。mesh 的对分随边长线性，节点数平方时每节点份额下降——这是弱扩展仍可能通信饱和的几何原因。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把龙芯/某款网的商标当拓扑课。路由算法与死锁下一课才禁止环。不要写成交易所网络。</p><p>后课默认：片上默认想 mesh 一类规则图。路由必须保证不会环形等待缓冲。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>mesh 易布线、直径较大；torus 减直径；fat-tree 堆对分。</li><li>片上与机柜的最优图不同。</li><li>死锁避免的路由规则是下一课。</li><li>出处：Dally and Towles；Leiserson, <em>IEEE TC</em>, 1985。</li></ul>',8))])}const D=r(m,[["render",p]]);export{A as __pageData,D as default};
